					WPS: 2,
					HasSecondaryChannelAbove: 4,
					HasSecondaryChannelBelow: 8,
					IEEE_802_11B: 256,
					IEEE_802_11A: 512,
					IEEE_802_11G: 1024,
					IEEE_802_11N: 2048,
					IEEE_802_11AC: 4096,
