/**
 * Base class for analog sensor servers
 * @category Servers
 */
class AnalogSensorServer extends SensorServer {
    constructor(serviceClass, options) {
        super(serviceClass, options);
        const { minReading, maxReading, inactiveThreshold, activeThreshold, readingResolution, } = options || {};
        if (minReading !== undefined)
            this.addRegister(SystemReg.MinReading, [minReading]);
        if (maxReading !== undefined)
            this.addRegister(SystemReg.MaxReading, [maxReading]);
        if (readingResolution !== undefined)
            this.addRegister(SystemReg.ReadingResolution, [
                readingResolution,
            ]);
        if (inactiveThreshold !== undefined ||
            this.activeThreshold !== undefined) {
            if (inactiveThreshold !== undefined)
                this.inactiveThreshold = this.addRegister(SystemReg.InactiveThreshold, [inactiveThreshold]);
            if (activeThreshold !== undefined)
                this.activeThreshold = this.addRegister(SystemReg.ActiveThreshold, [activeThreshold]);
            this.levelDetector = new LevelDetector(this);
        }
    }
}

class RainGaugeServer extends AnalogSensorServer {
    constructor(options) {
        super(SRV_RAIN_GAUGE, {
            readingValues: [0],
        });
        this._tiltCount = 0;
        this._level = 0;
        const { bucketSize } = options || {};
        this.precipitationPrecision = this.addRegister(RainGaugeReg.PrecipitationPrecision, [bucketSize || 0.2794]);
        this._level = 0;
    }
    get tiltCount() {
        return this._tiltCount;
    }
    get level() {
        return this._level;
    }
    async rain(fraction) {
        if (!fraction)
            return;
        this._level += fraction;
        if (this._level >= 0.7)
            await this.tilt();
        else
            this.emit(CHANGE);
    }
    async tilt() {
        this._tiltCount++;
        this._level = 0;
        const [bucket] = this.precipitationPrecision.values();
        const [current] = this.reading.values();
        this.reading.setValues([current + (bucket || 0.2)]);
        this.emit(CHANGE);
    }
}

